// Enable CORS
app.use('*', cors())

// Middleware: Log binding availability for debugging
app.use('*', async (c, next) => {
  // Log binding status for API routes (helps debug production issues)
  if (c.req.path.startsWith('/api/')) {
    console.log(`🔍 [${c.req.method}] ${c.req.path} - DB binding: ${!!c.env?.DB}`)
  }
  await next()
})

// Bank agents (role 5): only read scoped funding requests, sidebar request counts, and auth logout.
app.use('/api/*', async (c, next) => {
  const p = c.req.path
  if (
    p === '/api/auth/login' ||
    p === '/api/auth/logout' ||
    p.startsWith('/api/auth/forgot') ||
    p.startsWith('/api/auth/reset')
  ) {
    await next()
    return
  }
  const info = await getUserInfo(c)
  if (normalizeRoleId(info.roleId) !== 5) {
    await next()
    return
  }
  const method = c.req.method
  if (p === '/api/financing-requests' && method === 'GET') {
    await next()
    return
  }
  if (p === '/api/sidebar-filter-counts' && method === 'GET') {
    await next()
    return
  }
  return c.json({ success: false, error: 'غير مصرح' }, 403)
})

// Bank agents: only admin + API (each further restricted). No calculator, home, /c/*, packages, etc.
app.use('*', async (c, next) => {
  if (c.req.method === 'OPTIONS') {
    await next()
    return
  }
  const path = c.req.path || ''
  if (path.startsWith('/admin/')) {
    await next()
    return
  }
  if (path.startsWith('/api/')) {
    await next()
    return
  }
  const info = await getUserInfo(c)
  if (!info.userId || normalizeRoleId(info.roleId) !== 5) {
    await next()
    return
  }
  if (path === '/login' || path === '/forgot-password' || path.startsWith('/.well-known')) {
    await next()
    return
  }
  return c.redirect('/admin/requests')
})

// ===================================
// MULTI-TENANT MIDDLEWARE & HELPERS
// ===================================

// Helper: Get tenant from subdomain or slug
async function getTenant(c: any): Promise<any> {
  // Safety check for DB binding
  if (!c.env?.DB) {
    console.error('❌ getTenant: DB binding not available')
    return null
  }
  
  // Try to get from subdomain first (e.g., tamweel1.tamweel.app)
  const host = (c.req.header('host') || '').split(':')[0]
  const subdomain = host.split('.')[0]
  
  // Try to get from URL path (e.g., /c/tamweel-1/calculator)
  const pathMatch = c.req.path.match(/^\/c\/([^\/]+)/)
  const slug = pathMatch ? pathMatch[1] : null
  
  // Search in database
  let tenant = null
  
  if (subdomain && subdomain !== 'localhost' && subdomain !== '3000-ii8t2q2dzwwe7ckmslxss-3844e1b6') {
    tenant = await c.env.DB.prepare(`
      SELECT * FROM tenants 
      WHERE subdomain = ? AND status = 'active'
      LIMIT 1
    `).bind(subdomain).first()
  }
  
  if (!tenant && slug) {
    tenant = await c.env.DB.prepare(`
      SELECT * FROM tenants 
      WHERE slug = ? AND status = 'active'
      LIMIT 1
    `).bind(slug).first()
  }
  
  // Fallback: use tenant_id = 1 (default company) if no tenant found
  if (!tenant) {
    tenant = await c.env.DB.prepare(`
      SELECT * FROM tenants WHERE id = 1 LIMIT 1
    `).bind().first()
  }
  
  return tenant
}

function normalizeAuthToken(rawToken: string): string | null {
  const trimmed = rawToken.trim()
  if (!trimmed) {
    return null
  }

  let decodedToken = trimmed
  try {
    decodedToken = decodeURIComponent(trimmed)
  } catch {
    // If the token isn't URI-encoded, use it as-is.
  }

  const base64 = decodedToken.replace(/-/g, '+').replace(/_/g, '/')
  const remainder = base64.length % 4
  if (remainder === 1) {
    return null
  }

  const padding = remainder === 0 ? '' : '='.repeat(4 - remainder)
  return base64 + padding
}

function parseOptionalInt(value?: string): number | null {
  if (!value || value === 'null' || value === 'undefined') {
    return null
  }
  const parsed = Number.parseInt(value, 10)
  return Number.isNaN(parsed) ? null : parsed
}

function parseLoginTimestampToMs(value?: string | null): number | null {
  if (!value) {
    return null
  }
  // SQLite timestamps are commonly stored as "YYYY-MM-DD HH:MM:SS[.SSS]".
  // Normalize to ISO-8601 UTC to compare against token issue time.
  const normalized = value.includes('T') ? value : value.replace(' ', 'T')
  const withTimezone = /Z$|[+-]\d\d:\d\d$/.test(normalized) ? normalized : `${normalized}Z`
  const ms = Date.parse(withTimezone)
  return Number.isNaN(ms) ? null : ms
}

const DEFAULT_OBLIGATION_TYPE_NAMES = [
  'قرض شخصي',
  'قرض عقاري',
  'تمويل سيارة قائم',
  'بطاقة ائتمان',
  'تمويل تعاوني',
  'تقسيط / شراء بالأقساط',
  'سلفة راتب',
  'التزامات أخرى',
] as const

async function fetchObligationTypeNamesForTenant(
  db: Bindings['DB'],
  tenantId: number | null
): Promise<string[]> {
  try {
    let rows: { type_name?: string }[]
    if (tenantId != null) {
      const r = await db
        .prepare(
          'SELECT type_name FROM obligation_types WHERE is_active = 1 AND (tenant_id IS NULL OR tenant_id = ?) ORDER BY sort_order ASC, type_name ASC'
        )
        .bind(tenantId)
        .all()
      rows = (r.results || []) as { type_name?: string }[]
    } else {
      const r = await db
        .prepare(
          'SELECT type_name FROM obligation_types WHERE is_active = 1 AND tenant_id IS NULL ORDER BY sort_order ASC, type_name ASC'
        )
        .all()
      rows = (r.results || []) as { type_name?: string }[]
    }
    const names = rows.map((row) => row.type_name).filter((n): n is string => typeof n === 'string' && n.length > 0)
    return names.length > 0 ? names : [...DEFAULT_OBLIGATION_TYPE_NAMES]
  } catch {
    return [...DEFAULT_OBLIGATION_TYPE_NAMES]
  }
}

function parseRoleId(roleId: unknown): number | null {
  if (roleId == null || roleId === '') return null
  const n = typeof roleId === 'number' ? roleId : parseInt(String(roleId), 10)
  return Number.isNaN(n) ? null : n
}

function normalizeRoleId(roleId: unknown): number | null {
  const n = parseRoleId(roleId)
  if (n === null) {
    return null
  }
  const legacyMap: Record<number, number> = {
    11: 1,
    12: 2,
    13: 3,
    14: 4
  }
  return legacyMap[n] ?? n
}

function jsonForInlineScript(value: unknown): string {
  return JSON.stringify(value).replace(/</g, '\\u003c')
}

function getRoleDisplayName(roleId: unknown, roleName: string | null | undefined): string {
  const normalizedRoleId = normalizeRoleId(roleId)
  const raw = (roleName || '').trim()
  const rn = raw.toLowerCase()

  if (normalizedRoleId === 1) return 'مدير النظام'
  // Prefer DB label (e.g. حساب شركة) for company accounts
  if (normalizedRoleId === 2) return raw || 'حساب شركة'
  // Numeric 3 = sales supervisor (even if an old migration relabeled the roles row as "employee"/موظف)
  if (normalizedRoleId === 3) return 'مشرف المبيعات'
  if (normalizedRoleId === 4) return 'موظف'
  if (normalizedRoleId === 5) return 'موظف التمويل'

  // Legacy English keys from older seeds / custom role rows (when role_id is missing or non-standard)
  if (rn === 'supervisor') return 'مشرف المبيعات'
  if (rn === 'employee') return 'موظف'
  if (rn === 'company_admin') return 'حساب شركة'
  if (rn === 'super_admin') return 'مدير النظام'
  if (raw === 'موظف') return 'موظف'
  if (raw === 'مشرف' || raw.includes('مشرف')) return 'مشرف المبيعات'

  return raw || 'غير محدد'
}

/** توزيع العملاء: مدير النظام (1) أو حساب شركة (2) فقط — لا يشمل مشرف المبيعات (3) أو الموظف (4) */
function canManageCustomerAssignments(roleId: number | null): boolean {
  return roleId === 1 || roleId === 2
}

async function canUserAccessCustomer(
  db: D1Database,
  userInfo: { userId: number | null; tenantId: number | null; roleId: number | null },
  customer: { id: number; tenant_id: number | null } | null
): Promise<boolean> {
  if (!userInfo.userId || !userInfo.roleId || !customer) return false
  if (userInfo.roleId === 1) return true
  if (userInfo.tenantId == null || customer.tenant_id == null || customer.tenant_id !== userInfo.tenantId) return false
  if (userInfo.roleId === 4) {
    const assignment = await db
      .prepare('SELECT 1 as ok FROM customer_assignments WHERE customer_id = ? AND employee_id = ? LIMIT 1')
      .bind(customer.id, userInfo.userId)
      .first<{ ok: number }>()
    return Boolean(assignment?.ok)
  }
  return userInfo.roleId === 2 || userInfo.roleId === 3
}

// Get tenant_id for current user (for multi-tenancy filtering)
async function getUserInfo(
  c: any
): Promise<{
  userId: number | null
  tenantId: number | null
  roleId: number | null
  tokenRoleId: number | null
  assignedBankId: number | null
}> {
  try {
    console.log('🔍 [getUserInfo] Starting user info retrieval...')
    // Try to get token from Authorization Header (for API calls)
    let token = c.req.header('Authorization')?.replace('Bearer ', '')
    console.log('🔍 [getUserInfo] Token from header:', token ? 'Found' : 'Not found')
    
    // If not in header, try to get from cookie (for HTML pages)
    if (!token) {
      const cookieHeader = c.req.header('Cookie')
      console.log('🔍 [getUserInfo] Cookie header:', cookieHeader ? 'Present' : 'Missing')
      if (cookieHeader) {
        const cookies = cookieHeader.split(';').map((cookie: string) => cookie.trim())
        const authCookie = cookies.find((cookie: string) => cookie.startsWith('authToken='))
        if (authCookie) {
          // Do not use split('=')[1] — base64 tokens often contain '=' padding; that truncates the value.
          token = authCookie.startsWith('authToken=')
            ? authCookie.slice('authToken='.length)
            : ''
          console.log('✅ [getUserInfo] Token found in cookie')
        } else {
          console.log('❌ [getUserInfo] No authToken cookie found')
        }
      }
    }
    
    if (!token) {
      console.log('❌ [getUserInfo] No token found in header or cookie')
      const queryTenantId = c.req.query('tenant_id')
      return {
        userId: null,
        tenantId: queryTenantId ? parseInt(queryTenantId) : null,
        roleId: null,
        tokenRoleId: null,
        assignedBankId: null
      }
    }
    
    console.log('🔍 [getUserInfo] Token found:', token.substring(0, 20) + '...')

    console.log('🔍 [getUserInfo] Normalizing token...')
    const normalizedToken = normalizeAuthToken(token)
    if (!normalizedToken) {
      console.log('❌ [getUserInfo] Invalid token format after normalization')
      return { userId: null, tenantId: null, roleId: null, tokenRoleId: null, assignedBankId: null }
    }

    console.log('🔍 [getUserInfo] Decoding token...')
    const decoded = atob(normalizedToken)
    console.log('🔍 [getUserInfo] Decoded token:', decoded.substring(0, 50) + '...')
    const parts = decoded.split(':')
    console.log('🔍 [getUserInfo] Token parts:', parts.length, 'parts')
    const userId = parseOptionalInt(parts[0])
    if (!userId) {
      console.log('❌ [getUserInfo] Invalid token payload - no userId')
      return { userId: null, tenantId: null, roleId: null, tokenRoleId: null, assignedBankId: null }
    }

    const tenantIdFromToken = parseOptionalInt(parts[1])
    const tokenRoleId = normalizeRoleId(parseOptionalInt(parts[2]))
    const tokenIssuedAtMs = parseOptionalInt(parts[3])
    if (!tokenIssuedAtMs) {
      console.log('❌ [getUserInfo] Invalid token payload - missing issue timestamp')
      return { userId: null, tenantId: null, roleId: null, tokenRoleId: null, assignedBankId: null }
    }
    console.log('🔍 [getUserInfo] Parsed:', { userId, tenantIdFromToken, tokenRoleId, tokenIssuedAtMs })
    
    // Safety check for DB binding
    if (!c.env?.DB) {
      console.error('❌ [getUserInfo] DB binding not available')
      return { userId: null, tenantId: null, roleId: null, tokenRoleId: tokenRoleId ?? null, assignedBankId: null }
    }
    
    console.log('🔍 [getUserInfo] Querying database for user:', userId)
    const user = await c.env.DB.prepare(`
      SELECT id, tenant_id, role_id, last_login, assigned_bank_id FROM users WHERE id = ?
    `).bind(userId).first()
    
    if (!user) {
      console.log('❌ [getUserInfo] User not found in database')
      return { userId: null, tenantId: null, roleId: null, tokenRoleId, assignedBankId: null }
    }
    
    console.log('✅ [getUserInfo] User found:', { id: user.id, tenant_id: user.tenant_id, role_id: user.role_id })

    const userLastLoginMs = parseLoginTimestampToMs((user as { last_login?: string | null }).last_login ?? null)
    if (userLastLoginMs && tokenIssuedAtMs < userLastLoginMs) {
      console.log('❌ [getUserInfo] Token invalidated by a newer login', {
        tokenIssuedAtMs,
        userLastLoginMs
      })
      return { userId: null, tenantId: null, roleId: null, tokenRoleId: null, assignedBankId: null }
    }
    
    // Super Admin (role_id = 1) can see all data
    const normalizedRoleId = normalizeRoleId(user.role_id)
    const assignedBankFromRow = (user as { assigned_bank_id?: number | null }).assigned_bank_id
    const assignedBankId =
      assignedBankFromRow != null && !Number.isNaN(Number(assignedBankFromRow))
        ? Number(assignedBankFromRow)
        : null

    if (normalizedRoleId === 1) {
      const queryTenantId = c.req.query('tenant_id')
      const result = { userId: user.id, tenantId: queryTenantId ? parseInt(queryTenantId) : null, roleId: 1, tokenRoleId, assignedBankId: null }
      console.log('✅ [getUserInfo] Returning super admin info:', result)
      return result
    }
    
    // For other roles: DB is source of truth for which company (tenant) this user belongs to.
    // Stale JWT tenant segments must not override users.tenant_id (fixes customer/contract scoping).
    const dbTenantId = (user as { tenant_id?: number | null }).tenant_id
    const result = {
      userId: user.id,
      tenantId: dbTenantId != null ? dbTenantId : tenantIdFromToken,
      roleId: normalizedRoleId,
      tokenRoleId,
      assignedBankId: normalizedRoleId === 5 ? assignedBankId : null
    }
    console.log('✅ [getUserInfo] Returning user info:', result)
    return result
  } catch (error: any) {
    // Aggressive debug dump for getUserInfo errors
    const errorDump = {
      message: error?.message || 'Unknown error',
      name: error?.name || 'Error',
      stack: error?.stack || 'No stack trace',
      error_stringified: (() => {
        try {
          return JSON.stringify(error, Object.getOwnPropertyNames(error), 2)
        } catch (e) {
          return `Failed to stringify: ${e}`
        }
      })()
    }
    
    console.error('❌ [getUserInfo] ERROR DUMP:', errorDump)
    // Don't throw - return null values so request can continue
    return { userId: null, tenantId: null, roleId: null, tokenRoleId: null, assignedBankId: null }
  }
}

async function validateBankAgentForFinancingRequest(
  db: D1Database,
  tenantId: number,
  bankId: number,
  agentUserId: number
): Promise<boolean> {
  const row = await db
    .prepare(
      `SELECT 1 AS ok FROM users
       WHERE id = ? AND is_active = 1 AND role_id = 5
         AND tenant_id = ? AND assigned_bank_id = ?`
    )
    .bind(agentUserId, tenantId, bankId)
    .first()
  return Boolean(row)
}

async function validateAssignedBankBelongsToTenant(
  db: D1Database,
  tenantId: number,
  bankId: number
): Promise<boolean> {
  try {
    const row = await db
      .prepare(
        `SELECT id FROM banks WHERE id = ? AND is_active = 1 AND (tenant_id = ? OR tenant_id IS NULL)`
      )
      .bind(bankId, tenantId)
      .first()
    return Boolean(row)
  } catch {
    const row = await db
      .prepare(`SELECT id FROM banks WHERE id = ? AND (tenant_id = ? OR tenant_id IS NULL)`)
      .bind(bankId, tenantId)
      .first()
    return Boolean(row)
  }
}

async function getUserTenantId(c: any): Promise<number | null> {
  const info = await getUserInfo(c)
  return info.tenantId
}

/**
 * Same customer scope as `/admin/requests/new` (role + tenant).
 * Used server-side so lists match without a separate API round-trip.
 *
 * `scopeSuperAdminToTenant`: when true (contracts new form), super-admins are limited to
 * `?tenant_id=` or `users.tenant_id` so the dropdown never lists every company at once.
 */
async function loadCustomersForAdminForms(
  c: any,
  userInfo: { userId: number | null; tenantId: number | null; roleId: number | null },
  opts?: { scopeSuperAdminToTenant?: boolean }
): Promise<{ results: any[] }> {
  let customersQuery = 'SELECT id, full_name, phone, national_id, city, tenant_id FROM customers'
  const customersParams: any[] = []

  if (userInfo.roleId === 1) {
    if (opts?.scopeSuperAdminToTenant) {
      let tid: number | null = null
      const q = c.req.query('tenant_id')
      if (q != null && /^\d+$/.test(String(q))) {
        tid = parseInt(String(q), 10)
      }
      if (tid == null && userInfo.userId) {
        const row = (await c.env.DB.prepare('SELECT tenant_id FROM users WHERE id = ?').bind(userInfo.userId).first()) as {
          tenant_id: number | null
        } | null
        if (row?.tenant_id != null) tid = row.tenant_id
      }
      if (tid == null) {
        return { results: [] }
      }
      customersQuery += ' WHERE tenant_id = ?'
      customersParams.push(tid)
    }
    // else: legacy — SaaS super-admin sees all customers (e.g. financing request form)
  } else if (userInfo.roleId === 2 || userInfo.roleId === 3) {
    if (!userInfo.tenantId) {
      return { results: [] }
    }
    customersQuery += ' WHERE tenant_id = ?'
    customersParams.push(userInfo.tenantId)
  } else if (userInfo.roleId === 4) {
    // Employee can browse only assigned customers in their company scope.
    if (!userInfo.tenantId || !userInfo.userId) {
      return { results: [] }
    }
    customersQuery += ` WHERE tenant_id = ? AND EXISTS (
      SELECT 1 FROM customer_assignments ca
      WHERE ca.customer_id = customers.id AND ca.employee_id = ?
    )`
    customersParams.push(userInfo.tenantId, userInfo.userId)
  } else {
    customersQuery += ' WHERE 1 = 0'
  }
  customersQuery += ' ORDER BY full_name'
  const customers = customersParams.length
    ? await c.env.DB.prepare(customersQuery).bind(...customersParams).all()
    : await c.env.DB.prepare(customersQuery).all()
  return { results: (customers.results || []) as any[] }
}

function isSuperAdminUser(info: { roleId: number | null; tokenRoleId: number | null }): boolean {
  // Treat as super-admin only if BOTH DB role and token role agree on 1.
  return info.roleId === 1 && (info.tokenRoleId === null || info.tokenRoleId === 1)
}

