// USERS APIs

// Get all users
app.get('/api/users', async (c) => {
  try {
    // Get user info including role_id
    const userInfo = await getUserInfo(c)
    if (!userInfo.userId) {
      return c.json({ success: false, error: 'Unauthorized' }, 401)
    }
    const roleId = userInfo.roleId
    const tenantId = userInfo.tenantId
    
    // Resolve role_name from u.role_id only (scalar subqueries). Avoid GROUP BY + permission JOINs —
    // SQLite can surface inconsistent non-aggregated columns; old rows then showed wrong role_name (e.g. "employee").
    let query = `
      SELECT u.*,
             (SELECT role_name FROM roles WHERE id = u.role_id) AS role_name,
             (SELECT description FROM roles WHERE id = u.role_id) AS role_description,
             t.company_name AS tenant_name,
             (SELECT COUNT(DISTINCT permission_id) FROM role_permissions WHERE role_id = u.role_id) AS permissions_count
      FROM users u
      LEFT JOIN tenants t ON u.tenant_id = t.id`
    
    // Superadmin (role_id = 1) can see all users
    // Other roles see only their tenant's users
    if (roleId !== 1 && tenantId) {
      query += ` WHERE u.tenant_id = ${tenantId}`
    }
    
    query += `
      ORDER BY u.id DESC`
    
    const { results } = await c.env.DB.prepare(query).all()
    const normalizedResults = (results || []).map((u: any) => ({
      ...u,
      role_name: getRoleDisplayName(u.role_id, u.role_name)
    }))
    return c.json({ success: true, data: normalizedResults })
  } catch (error: any) {
    return c.json({ success: false, error: error.message }, 500)
  }
})

// Add user
app.post('/api/users', async (c) => {
  try {
    const formData = await c.req.formData()
    const username = formData.get('username')
    const password = formData.get('password')
    const full_name = formData.get('full_name')
    const email = formData.get('email')
    const phone = formData.get('phone')
    const role_id = formData.get('role_id')
    const subscription_id = formData.get('subscription_id') || null
    const is_active = formData.get('is_active') || '1'
    
    // Get user info to check role
    const userInfo = await getUserInfo(c);
    if (!userInfo.userId) {
      return c.json({ success: false, error: 'Unauthorized' }, 401)
    }

    const requestedRoleId = Number.parseInt(String(role_id || ''), 10)
    if (Number.isNaN(requestedRoleId)) {
      return c.json({ success: false, error: 'Invalid role_id' }, 400)
    }

    // Only super admin can create SaaS super admin users (role_id = 1)
    if (requestedRoleId === 1 && !isSuperAdminUser(userInfo)) {
      return c.json({ success: false, error: 'Forbidden: cannot grant SaaS role' }, 403)
    }
    
    // Get tenant_id from form data (if provided by super admin)
    // If not provided, use the current user's tenant_id (for company admin adding users)
    let tenant_id: number | null = null
    const tenantRaw = formData.get('tenant_id')

    if (isSuperAdminUser(userInfo)) {
      if (tenantRaw != null && String(tenantRaw).trim() !== '') {
        const parsed = parseInt(String(tenantRaw), 10)
        tenant_id = Number.isNaN(parsed) ? null : parsed
      } else {
        tenant_id = null
      }
    } else {
      // Non-superadmin: ignore any provided tenant_id to prevent cross-tenant creation
      if (!userInfo.tenantId) {
        return c.json({ success: false, error: 'No tenant context' }, 400)
      }
      tenant_id = userInfo.tenantId
    }

    const assignedBankRaw = formData.get('assigned_bank_id')
    let assigned_bank_id: number | null = null
    if (requestedRoleId === 5) {
      const canCreateBankAgent = isSuperAdminUser(userInfo) || userInfo.roleId === 2
      if (!canCreateBankAgent) {
        return c.json({ success: false, error: 'غير مسموح بإنشاء موظف التمويل' }, 403)
      }
      const tid = typeof tenant_id === 'number' ? tenant_id : parseInt(String(tenant_id || ''), 10)
      if (!tid || Number.isNaN(tid)) {
        return c.json({ success: false, error: 'يجب اختيار الشركة لموظف التمويل' }, 400)
      }
      const bid = Number.parseInt(String(assignedBankRaw || ''), 10)
      if (Number.isNaN(bid) || bid <= 0) {
        return c.json({ success: false, error: 'يجب اختيار البنك لموظف التمويل' }, 400)
      }
      const okBank = await validateAssignedBankBelongsToTenant(c.env.DB, tid, bid)
      if (!okBank) {
        return c.json({ success: false, error: 'البنك غير صالح لهذه الشركة' }, 400)
      }
      assigned_bank_id = bid
    }
    
    // Check for duplicate username
    const existingUser = await c.env.DB.prepare(`
      SELECT id FROM users WHERE username = ?
    `).bind(username).first()
    
    if (existingUser) {
      return c.json({ 
        success: false, 
        error: 'اسم المستخدم موجود مسبقاً! الرجاء اختيار اسم مستخدم آخر.' 
      }, 400)
    }
    
    // Check for duplicate email if provided
    if (email) {
      const existingEmail = await c.env.DB.prepare(`
        SELECT id FROM users WHERE email = ?
      `).bind(email).first()
      
      if (existingEmail) {
        return c.json({ 
          success: false, 
          error: 'البريد الإلكتروني موجود مسبقاً! الرجاء استخدام بريد إلكتروني آخر.' 
        }, 400)
      }
    }
    
    const result = await c.env.DB.prepare(`
      INSERT INTO users (username, password, full_name, email, phone, role_id, subscription_id, is_active, tenant_id, assigned_bank_id)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `).bind(username, password, full_name, email, phone, requestedRoleId, subscription_id, is_active, tenant_id, assigned_bank_id).run()
    
    return c.json({ 
      success: true, 
      message: 'تم إضافة المستخدم بنجاح',
      userId: result.meta.last_row_id 
    })
  } catch (error: any) {
    console.error('Error adding user:', error)
    return c.json({ 
      success: false, 
      error: error.message || 'حدث خطأ أثناء إضافة المستخدم' 
    }, 500)
  }
})

